function MarqueeRow({ items, direction, speed = 0.05 }: {
  items: typeof reviews;
  direction: "left" | "right";
  speed?: number;
}) {
  const trackRef = useRef<HTMLDivElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const [activeIdx, setActiveIdx] = useState<number | null>(null);
  const animOffsetRef = useRef(0);
  const rafRef = useRef<number>(0);
  const pausedRef = useRef(false);
  const cardRefs = useRef<(HTMLDivElement | null)[]>([]);
  const lastRef = useRef<number | null>(null);
  const offsetRef = useRef(0);

  const doubled = [...items, ...items];

  useEffect(() => {
    const track = trackRef.current;
    if (!track) return;

    if (direction === "right") {
      const half = track.scrollWidth / 2;
      offsetRef.current = -half / 2;
      animOffsetRef.current = offsetRef.current;
      track.style.transform = `translateX(${offsetRef.current}px)`;
    }

    function step(ts: number) {
      if (!pausedRef.current) {
        if (lastRef.current !== null) {
          const delta = ts - lastRef.current;
          const half = track.scrollWidth / 2;
          if (direction === "left") {
            offsetRef.current -= delta * speed;
            if (Math.abs(offsetRef.current) >= half) offsetRef.current += half;
          } else {
            offsetRef.current += delta * speed;
            if (offsetRef.current >= 0) offsetRef.current -= half;
          }
          animOffsetRef.current = offsetRef.current;
          track.style.transform = `translateX(${offsetRef.current}px)`;
        }
        lastRef.current = ts;
      } else {
        lastRef.current = null;
      }
      rafRef.current = requestAnimationFrame(step);
    }

    rafRef.current = requestAnimationFrame(step);
    return () => cancelAnimationFrame(rafRef.current);
  }, [direction, speed]);

  const handleMouseEnter = useCallback((globalIdx) => {
    pausedRef.current = true;
    setActiveIdx(globalIdx % items.length);
  }, [items.length]);

  const handleMouseLeave = useCallback(() => {
    pausedRef.current = false;
    setActiveIdx(null);
  }, []);

  return (
    <div ref={wrapperRef} style={{ overflow: "hidden", padding: "16px 0", cursor: "default" }}>
      <div ref={trackRef} style={{ display: "flex", width: "max-content" }}>
        {doubled.map((r, i) => (
          <Card
            key={i}
            r={r}
            isActive={activeIdx === i % items.length}
            cardRef={(el) => { cardRefs.current[i] = el; }}
            onMouseEnter={() => handleMouseEnter(i)}
            onMouseLeave={handleMouseLeave}
          />
        ))}
      </div>
    </div>
  );
}

